mapper.select:
select
notice.*
from notice notice

    and notice.id = #{id}
    and notice.banner_img = #{bannerImg}
    and notice.content = #{content}
    and notice.info = #{info}
    and notice.create_time = #{createTime}
    and notice.title like concat('%',#{title},'%')
    and notice.type = #{type}


    limit #{current},#{pageSize}

select count(*) from notice notice

    and notice.id = #{id}
    and notice.banner_img = #{bannerImg}
    and notice.content = #{content}
    and notice.info = #{info}
    and notice.create_time = #{createTime}
    and notice.title like concat('%',#{title},'%')
    and notice.type = #{type}
